export * as Toolbar from './toolbar.tsx';
export type {
  ButtonOwnProps as ToolbarButtonOwnProps,
  ButtonProps as ToolbarButtonProps,
  RootOwnProps as ToolbarRootOwnProps,
  RootProps as ToolbarRootProps,
  ToggleOwnProps as ToolbarToggleOwnProps,
  ToggleProps as ToolbarToggleProps,
} from './toolbar.tsx';

@layer hj.components {
  /* Customise: --hj-toolbar-size (button height) · --hj-toolbar-radius · --hj-toolbar-gap */
  .hj-toolbar-root {
    --_s: var(--hj-toolbar-size, 36px);
    display: inline-flex;
    align-items: center;
    gap: var(--hj-toolbar-gap, 2px);
    max-width: 100%;
    font-family: var(--hj-font-sans);
  }
  .hj-toolbar-root[data-variant='surface'] {
    padding: calc(4px * var(--hj-density));
    border-radius: var(--hj-toolbar-radius, var(--hj-radius-sm));
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-surface-2);
    box-shadow: inset 0 0 0 1px var(--hj-line);
  }
  .hj-toolbar-root[data-orientation='vertical'] {
    flex-direction: column;
  }
  .hj-toolbar-root[data-disabled] {
    opacity: 0.4;
  }

  .hj-toolbar-group {
    display: flex;
    align-items: center;
    gap: inherit;
  }
  .hj-toolbar-root[data-orientation='vertical'] .hj-toolbar-group {
    flex-direction: column;
  }

  .hj-toolbar-button,
  .hj-toolbar-link {
    position: relative;
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    gap: calc(6px * var(--hj-density));
    height: var(--_s);
    min-width: var(--_s);
    padding: 0 calc(10px * var(--hj-density));
    border: 0;
    border-radius: calc(var(--hj-toolbar-radius, var(--hj-radius-sm)) - 4px);
    corner-shape: var(--hj-corner-shape, round);
    background: transparent;
    color: var(--hj-fg-dim);
    font: 600 13.5px / 1 var(--hj-font-sans);
    text-decoration: none;
    white-space: nowrap;
    cursor: pointer;
    user-select: none;
    -webkit-tap-highlight-color: transparent;
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      color var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-snappy) var(--hj-ease-snappy);
  }
  /* 44px hit area around a 36px button */
  .hj-toolbar-button::before {
    content: '';
    position: absolute;
    inset: -4px -1px;
  }
  .hj-toolbar-button[data-icon-only] {
    width: var(--_s);
    padding: 0;
    font-size: 18px;
  }
  .hj-toolbar-button .hj-icon {
    font-size: 18px;
  }
  .hj-toolbar-button:hover:not([data-disabled]),
  .hj-toolbar-link:hover {
    background: color-mix(in srgb, var(--hj-fg) 6%, transparent);
    color: var(--hj-fg);
  }
  .hj-toolbar-button:active:not([data-disabled]) {
    transform: scale(var(--hj-press));
    transition-duration: var(--hj-dur-fast), var(--hj-dur-fast), 70ms;
  }
  /* Pressed toggles and open menus read as chosen: accent on accent-soft. */
  .hj-toolbar-button[data-pressed],
  .hj-toolbar-button[data-popup-open] {
    background: var(--hj-accent-soft);
    color: var(--hj-accent-text);
  }
  .hj-toolbar-button[data-disabled] {
    opacity: 0.4;
    cursor: not-allowed;
  }
  .hj-toolbar-button:focus-visible,
  .hj-toolbar-link:focus-visible {
    outline-offset: -2px;
  }

  .hj-toolbar-link {
    color: var(--hj-accent-text);
  }

  .hj-toolbar-separator {
    flex: none;
    width: 1px;
    height: 20px;
    margin: 0 calc(4px * var(--hj-density));
    background: var(--hj-line);
  }
  .hj-toolbar-root[data-orientation='vertical'] .hj-toolbar-separator {
    width: 20px;
    height: 1px;
    margin: calc(4px * var(--hj-density)) 0;
  }

  .hj-toolbar-input {
    height: var(--_s);
    min-width: 0;
    width: 160px;
    padding: 0 calc(10px * var(--hj-density));
    border: 0;
    border-radius: calc(var(--hj-toolbar-radius, var(--hj-radius-sm)) - 4px);
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-surface);
    box-shadow: inset 0 0 0 1px var(--hj-line);
    color: var(--hj-fg);
    font: 500 13.5px / 1 var(--hj-font-sans);
    outline: none;
    caret-color: var(--hj-accent);
    transition: box-shadow var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-toolbar-input::placeholder {
    color: var(--hj-fg-mute);
  }
  .hj-toolbar-input:focus-visible {
    box-shadow: inset 0 0 0 1.5px var(--hj-accent);
    outline: none;
  }
  .hj-toolbar-input[data-disabled] {
    opacity: 0.4;
  }
}

'use client';
import { Toggle as BaseToggle } from '@base-ui/react/toggle';
import { Toolbar as Base } from '@base-ui/react/toolbar';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { part } from '../../system/part.tsx';
import type { HanjiPart } from '../../system/part.tsx';
import { cls, flag, withDefaults } from '../../system/slot.ts';

export const Group: HanjiPart<typeof Base.Group> = part(
  Base.Group,
  'Toolbar.Group',
  'hj-toolbar-group',
);
export const Separator: HanjiPart<typeof Base.Separator> = part(
  Base.Separator,
  'Toolbar.Separator',
  'hj-toolbar-separator',
);
export const Link: HanjiPart<typeof Base.Link> = part(Base.Link, 'Toolbar.Link', 'hj-toolbar-link');
export const Input: HanjiPart<typeof Base.Input> = part(
  Base.Input,
  'Toolbar.Input',
  'hj-toolbar-input',
);

export interface RootOwnProps {
  /** surface = a hairlined surface-2 tray (floating formatting bar) · plain = items only, on the page. */
  variant?: 'surface' | 'plain';
}
export interface RootProps extends RootOwnProps, Base.Root.Props {}

/** A row (or column) of controls that arrow keys move between as one tab stop. */
export function Root(props: RootProps): React.ReactElement {
  const config = useHanjiConfig();
  const { variant = 'surface', className, ...rest } = withDefaults(config, 'Toolbar.Root', props);
  return (
    <Base.Root
      {...rest}
      data-variant={variant}
      className={cls(config, 'Toolbar.Root', 'hj-toolbar-root', className)}
    />
  );
}

export interface ButtonOwnProps {
  /** Square button for a lone icon. Give it an aria-label. */
  iconOnly?: boolean;
}
export interface ButtonProps extends ButtonOwnProps, Base.Button.Props {}

/** A quiet 36px toolbar button. Compose with Menu.Trigger, Select.Trigger… through render. */
export function Button(props: ButtonProps): React.ReactElement {
  const config = useHanjiConfig();
  const { iconOnly = false, className, ...rest } = withDefaults(config, 'Toolbar.Button', props);
  return (
    <Base.Button
      {...rest}
      data-icon-only={flag(iconOnly)}
      className={cls(config, 'Toolbar.Button', 'hj-toolbar-button', className)}
    />
  );
}

export interface ToggleOwnProps {
  iconOnly?: boolean;
  pressed?: boolean;
  defaultPressed?: boolean;
  onPressedChange?: BaseToggle.Props['onPressedChange'];
  /** Identifies the toggle inside a ToggleGroup. */
  value?: string;
}
export interface ToggleProps extends ToggleOwnProps, Omit<Base.Button.Props, 'value'> {}

/**
 * A toolbar button that stays pressed (bold, align left…). It is a Base UI Toggle rendered
 * through Toolbar.Button, so it keeps the toolbar's roving focus. Inside a ToggleGroup it
 * becomes one-of-many.
 */
export function Toggle(props: ToggleProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    iconOnly = false,
    pressed,
    defaultPressed,
    onPressedChange,
    value,
    className,
    ...rest
  } = withDefaults(config, 'Toolbar.Toggle', props);
  return (
    <Base.Button
      {...rest}
      render={
        <BaseToggle
          pressed={pressed}
          defaultPressed={defaultPressed}
          onPressedChange={onPressedChange}
          value={value}
        />
      }
      data-icon-only={flag(iconOnly)}
      className={cls(config, 'Toolbar.Toggle', 'hj-toolbar-button', className)}
    />
  );
}
